//! Static recipe tables and recipe-array selection.
//!
//! (`preserveItemDataAInCraftedItem`), 5.4 (`baseGrowthRateForTreeType`), Appendix C (data);
//! The data block at the end of the file is generated by
//! `.json`.

use std::sync::OnceLock;

use crate::items::breeds::item_type_for_dodo_egg_breed;
use crate::types::enums::{DodoBreed, TreeType, WorkbenchType};
use crate::types::item_type::ItemType;
use crate::types::structs::CraftableItem;

/// All-zero row (padding rows of the static arrays).
const ZERO_ROW: CraftableItem = CraftableItem {
    crafted_item_type: 0,
    crafted_item_count: 0,
    required_items: [0; 8],
    required_item_counts: [0; 8],
    number_of_required_items: 0,
    seconds_required: 0,
    upgrade_level: 0,
    crafted_item_data_a: 0,
    crafted_item_data_b: 0,
    secondary_indicator_item: 0,
    required_item_data_bs: [0; 8],
};

/// Zero block returned for out-of-range levels (original reads neighbouring static data: UB-PARITY, never happens).
static ZERO_BLOCK: [CraftableItem; 32] = [ZERO_ROW; 32];

/// Helper called by the generated data: builds one `CraftableItem` row.
#[allow(clippy::too_many_arguments)]
const fn row(
    crafted: i32,
    count: i32,
    req: [i32; 8],
    req_count: [i32; 8],
    nreq: i32,
    secs: i32,
    upg: i32,
    data_a: u16,
    data_b: u16,
    secondary: i32,
    req_data_b: [i32; 8],
) -> CraftableItem {
    let mut r = [0u32; 8];
    let mut i = 0;
    while i < 8 {
        r[i] = req[i] as u32;
        i += 1;
    }
    CraftableItem {
        crafted_item_type: crafted as u32,
        crafted_item_count: count,
        required_items: r,
        required_item_counts: req_count,
        number_of_required_items: nreq,
        seconds_required: secs,
        upgrade_level: upg,
        crafted_item_data_a: data_a,
        crafted_item_data_b: data_b,
        secondary_indicator_item: secondary as u32,
        required_item_data_bs: req_data_b,
    }
}

/// Block `level` (of `per` rows) of a flat array, or a zero block of length `per` when out of range.
fn block(arr: &'static [CraftableItem], per: usize, level: i32) -> &'static [CraftableItem] {
    if level < 0 {
        return &ZERO_BLOCK[..per.min(32)];
    }
    let start = (level as usize).saturating_mul(per);
    if start >= arr.len() {
        return &ZERO_BLOCK[..per.min(32)];
    }
    &arr[start..start + per]
}

/// Runtime-built egg extractor table (`WORKBENCH_EGG_EXTRACTOR_CRAFTABLE_ITEMS[0]`).
static EGG_EXTRACTOR: OnceLock<[CraftableItem; 32]> = OnceLock::new();

/// `setupEggExtractorCraftableItems`: idempotent lazy initialiser; row `i` crafts the item of dodo breed
/// `i + 1`, count 2, needs one `ITEM_DODO_EGG` (91) whose dataB is the breed, 80 seconds.
pub fn setup_egg_extractor_craftable_items() {
    egg_extractor_table();
}

fn egg_extractor_table() -> &'static [CraftableItem; 32] {
    EGG_EXTRACTOR.get_or_init(|| {
        let mut t = [ZERO_ROW; 32];
        for (i, e) in t.iter_mut().enumerate() {
            let breed = (i + 1) as u16;
            e.crafted_item_type = item_type_for_dodo_egg_breed(DodoBreed(breed)).0;
            e.crafted_item_count = 2;
            e.required_items[0] = 91;
            e.required_item_counts[0] = 1;
            e.required_item_data_bs[0] = breed as i32;
            e.number_of_required_items = 1;
            e.seconds_required = 80;
        }
        t
    })
}

macro_rules! sel {
    ($arr:ident, $per:ident, $level:expr) => {
        block(&$arr, $per, $level)
    };
}

/// `craftableItemsForWorkbenchTypeAndLevel`: slice starting at the first recipe of `level` and ending
/// at the end of that level's block. Callers index with `< number_of_craftable_items_...`.
pub fn craftable_items_for_workbench_type_and_level(
    t: WorkbenchType,
    level: i32,
    is_cloud_game: bool,
    expert_mode: bool,
) -> &'static [CraftableItem] {
    let ty = t.0 as i32;
    let e = expert_mode;
    match ty {
        1 | 13 => {
            if level == 0 && is_cloud_game {
                return if e { &EXPERT_BASIC_PORTAL_LEVEL_ONE_CLOUD[..] } else { &BASIC_PORTAL_LEVEL_ONE_CLOUD[..] };
            }
            if e {
                sel!(EXPERT_BASIC_PORTAL, EXPERT_BASIC_PORTAL_PER_LEVEL, level)
            } else {
                sel!(BASIC_PORTAL, BASIC_PORTAL_PER_LEVEL, level)
            }
        }
        2 => {
            if e {
                sel!(EXPERT_WORKBENCH, EXPERT_WORKBENCH_PER_LEVEL, level)
            } else {
                sel!(WORKBENCH, WORKBENCH_PER_LEVEL, level)
            }
        }
        3 => {
            if e {
                sel!(EXPERT_WORKBENCH_CAMPFIRE, EXPERT_WORKBENCH_CAMPFIRE_PER_LEVEL, level)
            } else {
                sel!(WORKBENCH_CAMPFIRE, WORKBENCH_CAMPFIRE_PER_LEVEL, level)
            }
        }
        24 => sel!(WORKBENCH_EASEL, WORKBENCH_EASEL_PER_LEVEL, level),
        5 => {
            if e {
                sel!(EXPERT_WORKBENCH_WOOD, EXPERT_WORKBENCH_WOOD_PER_LEVEL, level)
            } else {
                sel!(WORKBENCH_WOOD, WORKBENCH_WOOD_PER_LEVEL, level)
            }
        }
        4 => {
            if e {
                sel!(EXPERT_WORKBENCH_WEAVE, EXPERT_WORKBENCH_WEAVE_PER_LEVEL, level)
            } else {
                sel!(WORKBENCH_WEAVE, WORKBENCH_WEAVE_PER_LEVEL, level)
            }
        }
        8 => {
            if e {
                sel!(EXPERT_WORKBENCH_KILN, EXPERT_WORKBENCH_KILN_PER_LEVEL, level)
            } else {
                sel!(WORKBENCH_KILN, WORKBENCH_KILN_PER_LEVEL, level)
            }
        }
        16 => {
            if e {
                sel!(EXPERT_WORKBENCH_ELECTRIC_KILN, EXPERT_WORKBENCH_ELECTRIC_KILN_PER_LEVEL, level)
            } else {
                sel!(WORKBENCH_ELECTRIC_KILN, WORKBENCH_ELECTRIC_KILN_PER_LEVEL, level)
            }
        }
        31 => sel!(WORKBENCH_PIZZA_OVEN, WORKBENCH_PIZZA_OVEN_PER_LEVEL, level),
        27 => {
            if e {
                sel!(EXPERT_WORKBENCH_ELECTRIC_PRESS, EXPERT_WORKBENCH_ELECTRIC_PRESS_PER_LEVEL, level)
            } else {
                sel!(WORKBENCH_ELECTRIC_PRESS, WORKBENCH_ELECTRIC_PRESS_PER_LEVEL, level)
            }
        }
        7 => {
            if e {
                sel!(EXPERT_WORKBENCH_PRESS, EXPERT_WORKBENCH_PRESS_PER_LEVEL, level)
            } else {
                sel!(WORKBENCH_PRESS, WORKBENCH_PRESS_PER_LEVEL, level)
            }
        }
        6 => {
            if e {
                sel!(EXPERT_WORKBENCH_TOOL, EXPERT_WORKBENCH_TOOL_PER_LEVEL, level)
            } else {
                sel!(WORKBENCH_TOOL, WORKBENCH_TOOL_PER_LEVEL, level)
            }
        }
        9 => {
            if e {
                sel!(EXPERT_WORKBENCH_FURNACE, EXPERT_WORKBENCH_FURNACE_PER_LEVEL, level)
            } else {
                sel!(WORKBENCH_FURNACE, WORKBENCH_FURNACE_PER_LEVEL, level)
            }
        }
        10 => {
            if e {
                sel!(EXPERT_WORKBENCH_CRAFT, EXPERT_WORKBENCH_CRAFT_PER_LEVEL, level)
            } else {
                sel!(WORKBENCH_CRAFT, WORKBENCH_CRAFT_PER_LEVEL, level)
            }
        }
        11 => sel!(WORKBENCH_MIX, WORKBENCH_MIX_PER_LEVEL, level),
        12 => sel!(WORKBENCH_DYE, WORKBENCH_DYE_PER_LEVEL, level),
        14 => {
            if e {
                sel!(EXPERT_WORKBENCH_METALWORK, EXPERT_WORKBENCH_METALWORK_PER_LEVEL, level)
            } else {
                sel!(WORKBENCH_METALWORK, WORKBENCH_METALWORK_PER_LEVEL, level)
            }
        }
        18 => sel!(WORKBENCH_ELECTRIC_METALWORK, WORKBENCH_ELECTRIC_METALWORK_PER_LEVEL, level),
        17 => {
            if e {
                sel!(EXPERT_WORKBENCH_ELECTRIC_FURNACE, EXPERT_WORKBENCH_ELECTRIC_FURNACE_PER_LEVEL, level)
            } else {
                sel!(WORKBENCH_ELECTRIC_FURNACE, WORKBENCH_ELECTRIC_FURNACE_PER_LEVEL, level)
            }
        }
        19 => sel!(WORKBENCH_ELECTRIC_STOVE, WORKBENCH_ELECTRIC_STOVE_PER_LEVEL, level),
        22 => {
            if e {
                sel!(EXPERT_WORKBENCH_ARMOR, EXPERT_WORKBENCH_ARMOR_PER_LEVEL, level)
            } else {
                sel!(WORKBENCH_ARMOR, WORKBENCH_ARMOR_PER_LEVEL, level)
            }
        }
        23 => sel!(WORKBENCH_TRAIN_YARD, WORKBENCH_TRAIN_YARD_PER_LEVEL, level),
        28 => {
            if e {
                sel!(EXPERT_WORKBENCH_COMPOST_BIN, EXPERT_WORKBENCH_COMPOST_BIN_PER_LEVEL, level)
            } else {
                sel!(WORKBENCH_COMPOST_BIN, WORKBENCH_COMPOST_BIN_PER_LEVEL, level)
            }
        }
        25 => {
            if e {
                sel!(EXPERT_WORKBENCH_BUILD, EXPERT_WORKBENCH_BUILD_PER_LEVEL, level)
            } else {
                sel!(WORKBENCH_BUILD, WORKBENCH_BUILD_PER_LEVEL, level)
            }
        }
        26 => sel!(WORKBENCH_REFINERY, WORKBENCH_REFINERY_PER_LEVEL, level),
        29 => sel!(WORKBENCH_SLUICE, WORKBENCH_SLUICE_PER_LEVEL, level),
        30 => {
            // `[0][0].craftedItemType == 0` test + lazy fill is equivalent to the OnceLock. Only level 0 exists.
            let tbl = egg_extractor_table();
            if level == 0 {
                &tbl[..]
            } else {
                &ZERO_BLOCK[..32]
            }
        }
        // 15, 20, 21 and everything outside 1..31: base of WORKBENCH, offset not applied.
        _ => &WORKBENCH[..WORKBENCH_PER_LEVEL],
    }
}

/// `preserveItemDataAInCraftedItem`: true for the 31 clothing/armor items whose data-A is copied to the
/// crafted item; `crafted_item_type` is ignored.
pub fn preserve_item_data_a_in_crafted_item(t: ItemType, _crafted_item_type: ItemType) -> bool {
    matches!(
        t.0,
        84 | 85 | 115 | 117 | 122 | 124 | 126 | 127 | 130 | 154 | 187..=198 | 278 | 287..=294
    )
}

/// `baseGrowthRateForTreeType`: f32 literals; unlisted types give 1.0.
pub fn base_growth_rate_for_tree_type(t: TreeType) -> f32 {
    match t.0 {
        1 => 0.25f32,
        2 => 0.5f32,
        3 => 0.25f32,
        4 => 1.0f32,
        5 => 0.25f32,
        6 => 0.5f32,
        7 => 0.35f32,
        8 => 0.25f32,
        9 => 0.1f32,
        10 => 0.2f32,
        _ => 1.0f32,
    }
}

