#[cfg(test)]
mod tests {
    use super::*;

    fn w(t: u32) -> WorkbenchType {
        WorkbenchType(t)
    }

    #[test]
    fn array_shapes() {
        assert_eq!(WORKBENCH.len(), WORKBENCH_PER_LEVEL * WORKBENCH_LEVELS);
        assert_eq!(EXPERT_WORKBENCH.len(), 2 * 30);
        assert_eq!(WORKBENCH_PER_LEVEL, 11);
        assert_eq!(BASIC_PORTAL_LEVEL_ONE_CLOUD.len(), 13);
        // WORKBENCH L0#0 (spec Appendix C): ITEM_CAMPFIRE x1 <- ITEM_STICK x10; 20s
        let r = &WORKBENCH[0];
        assert_eq!((r.crafted_item_type, r.number_of_required_items, r.seconds_required), (15, 1, 20));
        assert_eq!(r.required_item_data_bs, [-1, -1, -1, -1, -1, 0, 0, 0]);
        // requiredItemDataBs exceptions
        assert!(WORKBENCH_DYE
            .iter()
            .take(5)
            .filter(|r| r.crafted_item_type != 0 && r.crafted_item_type != 132)
            .all(|r| r.required_item_data_bs[0] == 0));
    }

    #[test]
    fn selection() {
        assert_eq!(craftable_items_for_workbench_type_and_level(w(1), 0, true, false).len(), 13);
        assert_eq!(craftable_items_for_workbench_type_and_level(w(13), 0, true, true).len(), 13);
        assert_eq!(craftable_items_for_workbench_type_and_level(w(1), 0, false, false).len(), 12);
        assert_eq!(craftable_items_for_workbench_type_and_level(w(1), 1, true, false).len(), 12);
        assert_eq!(craftable_items_for_workbench_type_and_level(w(30), 0, false, false).len(), 32);
        assert_eq!(
            craftable_items_for_workbench_type_and_level(w(2), 1, false, false).as_ptr(),
            WORKBENCH[11..].as_ptr()
        );
        assert_eq!(
            craftable_items_for_workbench_type_and_level(w(2), 3, false, true).as_ptr(),
            EXPERT_WORKBENCH[6..].as_ptr()
        );
        assert_eq!(craftable_items_for_workbench_type_and_level(w(15), 0, false, false).as_ptr(), WORKBENCH.as_ptr());
        assert_eq!(craftable_items_for_workbench_type_and_level(w(99), 3, false, false).as_ptr(), WORKBENCH.as_ptr());
        // out of range: zero block of the right length
        let z = craftable_items_for_workbench_type_and_level(w(2), 100, false, false);
        assert_eq!(z.len(), 11);
        assert!(z.iter().all(|r| r.crafted_item_type == 0));
        let z = craftable_items_for_workbench_type_and_level(w(2), -1, false, false);
        assert_eq!(z.len(), 11);
    }

    /// Checklist 6.1 #8.
    #[test]
    fn egg_extractor() {
        setup_egg_extractor_craftable_items();
        setup_egg_extractor_craftable_items();
        let s = craftable_items_for_workbench_type_and_level(w(30), 0, false, false);
        assert_eq!(s.len(), 32);
        for (i, r) in s.iter().enumerate() {
            let mut exp = ZERO_ROW;
            exp.crafted_item_type = item_type_for_dodo_egg_breed(DodoBreed(i as u16 + 1)).0;
            exp.crafted_item_count = 2;
            exp.required_items[0] = 91;
            exp.required_item_counts[0] = 1;
            exp.required_item_data_bs[0] = i as i32 + 1;
            exp.number_of_required_items = 1;
            exp.seconds_required = 80;
            assert_eq!(*r, exp);
            assert_ne!(r.crafted_item_type, 0);
        }
    }

    /// Checklist 6.1 #9.
    #[test]
    fn preserve_data_a() {
        let yes = [
            84, 85, 115, 117, 122, 124, 126, 127, 130, 154, 187, 188, 189, 190, 191, 192, 193, 194, 195, 196, 197, 198,
            278, 287, 288, 289, 290, 291, 292, 293, 294,
        ];
        assert_eq!(yes.len(), 31);
        for i in -5i32..1200 {
            assert_eq!(preserve_item_data_a_in_crafted_item(ItemType(i as u32), ItemType(0)), yes.contains(&i), "{i}");
        }
    }

    /// Checklist 6.1 #10.
    #[test]
    fn growth() {
        let exp = [1.0f32, 0.25, 0.5, 0.25, 1.0, 0.25, 0.5, 0.35, 0.25, 0.1, 0.2, 1.0, 1.0, 1.0];
        for (i, e) in exp.iter().enumerate() {
            assert_eq!(base_growth_rate_for_tree_type(TreeType(i as u32)).to_bits(), e.to_bits(), "{i}");
        }
    }

    #[test]
    fn row_builder_and_egg_extractor_levels() {
        // `row` normally runs at compile time only
        let r = row(5, 2, [1, 2, 3, 4, 5, 6, 7, 8], [8, 7, 6, 5, 4, 3, 2, 1], 8, 30, 1, 11, 12, 13, [-1; 8]);
        assert_eq!((r.crafted_item_type, r.crafted_item_count, r.number_of_required_items), (5, 2, 8));
        assert_eq!(r.required_items, [1, 2, 3, 4, 5, 6, 7, 8]);
        assert_eq!(r.required_item_counts, [8, 7, 6, 5, 4, 3, 2, 1]);
        assert_eq!(
            (r.seconds_required, r.upgrade_level, r.crafted_item_data_a, r.crafted_item_data_b),
            (30, 1, 11, 12)
        );
        assert_eq!(r.secondary_indicator_item, 13);
        assert_eq!(r.required_item_data_bs, [-1; 8]);
        // the egg extractor only has level 0
        let lvl1 = craftable_items_for_workbench_type_and_level(w(30), 1, false, false);
        assert_eq!(lvl1.len(), 32);
        assert!(lvl1.iter().all(|r| r.crafted_item_type == 0));
        assert_eq!(craftable_items_for_workbench_type_and_level(w(30), 0, false, false)[0].required_items[0], 91);
    }
}
